      if(d>250){e.x+=dx/d*e.speed*slow*dt;e.y+=dy/d*e.speed*slow*dt;}if(e.fireCd<=0&&d<700){e.aim=Math.atan2(dy,dx);e.windup=.8;e.fireCd=3.3;}
