          if(b.ronnySplash){b.ronnySplash=false;for(const other of combatTargets().filter(other=>other!==e&&!other.dead&&dist(other,e)<75+other.r).slice(0,2)){damageEnemy(other,.75*abilityPower(player),true);if(mode!=='playing')return;}burst(e.x,e.y,'#dec6ac',7,70);}
