    hasenbeinPhase++;player.hp=player.maxHp;player.invuln=1.6;player.enraged=true;
    player.speed=Math.min(142,player.speed+10);hasenbeinAttackCd=.7;hasenbeinSummonCd=Math.min(hasenbeinSummonCd,2.5);
