  function startHasenbeinKarnilIntro(){
    if(mode!=='playing'||hasenbeinKarnil)return;
    const hp=Math.round(65+(hasenbeinBuildThreat-1)*22);
    hasenbeinKarnil={x:clamp(player.x+140,90,W-90),y:clamp(player.y-60,165,H-95),r:75,hp,maxHp:hp,speed:90,phase:0,hit:0,shotCd:1.2,rockCd:3.5,contactCd:0,type:'boss',karnil:true};
    Object.assign(hasenbeinKarnil,duelFreePoint29(hasenbeinKarnil.x,hasenbeinKarnil.y,hasenbeinKarnil.r));
    mode='hasenbeinKarnilIntro';hasenbeinCinematicTime=3.3;resetInput();updateHasenbeinHud();
    showOverlay(`<span class="eyebrow">LETZTE PHASE · DIE ERDE BEBT</span><h2 id="overlayTitle">KARNIL KOMMT!</h2>${hasenbeinCinematicArt(false)}<p class="hasenbein-scene-copy">„Finger weg von meinem Hasen!“ Karnil durchbricht den Gartenzaun und kämpft jetzt an Hasenbeins Seite. ${characterRoster[hasenbeinRival?.characterId]?.name||'SNICKERS'} hat weiterhin nur einen Lebensbalken.</p><button class="secondary-button" id="hasenbeinSkipKarnil">KAMPF FORTSETZEN ↗</button>`);
    $('hasenbeinSkipKarnil').onclick=finishHasenbeinKarnilIntro;
    tone(78,.6,'sawtooth',.08,35);
  }
  function finishHasenbeinKarnilIntro(){
    if(mode!=='hasenbeinKarnilIntro')return;
    mode='playing';hasenbeinCinematicTime=0;hideOverlay();lastFrame=performance.now();
    announce('HASENBEIN + KARNIL',`PHASE ${hasenbeinPhase} / ${hasenbeinMaxPhases}`);
  }
  function showHasenbeinCredits(){
    if(mode!=='hasenbeinVictoryCutscene')return;
    mode='hasenbeinResult';hasenbeinCinematicTime=0;$('hasenbeinHud').classList.add('hidden');
    const rivalName=characterRoster[hasenbeinRival?.characterId]?.name||'SNICKERS',skinId=hasenbeinRival?.characterId&&hasenbeinRival.characterId!=='snickers'?`${hasenbeinRival.characterId}__hasenbeinVictor`:'hasenbeinVictor',rewardSkin=skins.find(s=>s.id===skinId)?.name||'HASENBEINS ALBTRAUM';showOverlay(`<span class="eyebrow">ABSPANN · HASENBEINS RACHE · ${hasenbeinDifficulty.toUpperCase()}</span><h2 id="overlayTitle">HEUTE JAGT DER HASE.</h2><p>Hasenbein hat ${rivalName} aus der Hall of Fame besiegt. Karnil bewacht das Feuer, und der General tanzt endlich seinen Siegestanz.</p>${hasenbeinCinematicArt(true)}<div class="hasenbein-credits"><span>IN DER HAUPTROLLE <strong>GENERAL HASENBEIN</strong></span><span>${hasenbeinKarnil?'RETTER IN LETZTER MINUTE':'ÜBERRASCHUNGSGAST AM FEUER'} <strong>KARNIL, DAS SAUFERKEL</strong></span><span>AM LAGERFEUER <strong>${rivalName}</strong></span><span>DAUER DER REVANCHE <strong>${formatTime(hasenbeinDuelTime)}</strong></span><span>FREIGESCHALTET <strong>${rewardSkin}</strong></span></div><div class="overlay-actions"><button class="primary-button" id="hasenbeinAgain">ANDEREN BUILD WÄHLEN ↗</button><button class="secondary-button" id="hasenbeinLeave">HAUPTMENÜ</button></div>`);
    $('hasenbeinAgain').onclick=showHasenbeinSelect;$('hasenbeinLeave').onclick=goMenu;
  }
  function advanceHasenbeinCinematic(dt){
    if(!['hasenbeinKarnilIntro','hasenbeinVictoryCutscene'].includes(mode))return;
    hasenbeinCinematicTime=Math.max(0,hasenbeinCinematicTime-dt);
    if(hasenbeinCinematicTime===0){if(mode==='hasenbeinKarnilIntro')finishHasenbeinKarnilIntro();else showHasenbeinCredits();}
  }
  function updateHasenbeinKarnil(dt){
    const k=hasenbeinKarnil,rival=hasenbeinRival;if(!k||k.hp<=0||!rival||rival.hp<=0)return;
    k.phase+=dt*4;k.hit=Math.max(0,k.hit-dt);
    const dx=rival.x-k.x,dy=rival.y-k.y,d=Math.hypot(dx,dy)||1;
    if(d>115){const from29={x:k.x,y:k.y};k.x+=dx/d*k.speed*dt;k.y+=dy/d*k.speed*dt;resolveDuelMotion29(k,from29,true);}
    k.shotCd-=dt;k.rockCd-=dt;k.contactCd=Math.max(0,k.contactCd-dt);
    if(d<540&&k.shotCd<=0){k.shotCd=2.9;const a=Math.atan2(dy,dx);for(const off of [-.12,0,.12])hasenbeinShot(k.x,k.y,a+off,330,hasenbeinDamage(3.5),'hasenbein',off===0);burst(k.x,k.y,'#eab58b',5,65);}
    if(d<650&&k.rockCd<=0){k.rockCd=7.2;hasenbeinHazards.push({x:rival.x,y:rival.y,r:94,wait:.8,life:.35,hit:false,damage:hasenbeinDamage(8),karnil:true});}
    if(d<k.r+rival.r&&k.contactCd<=0){k.contactCd=1.5;hasenbeinHitRival(hasenbeinDamage(2.5));}
  }
  function endHasenbeinDuel(won){
    if(mode!=='playing')return;
    resetInput();if(won){
      addAchievementProgress('hasenbein_'+hasenbeinDifficulty);
      mode='hasenbeinVictoryCutscene';hasenbeinCinematicTime=4.6;
      $('hasenbeinHud').classList.add('hidden');$('touchControls').classList.add('hidden');$('pauseButton').classList.add('hidden');
      showOverlay(`<span class="eyebrow">HASENBEIN MODUS · DER SIEG</span><h2 id="overlayTitle">HASENBEIN HAT SICH GERÄCHT!</h2>${hasenbeinCinematicArt(true)}<p class="hasenbein-scene-copy">Der General jubelt. Karnil schürt das Lagerfeuer und ${characterRoster[hasenbeinRival?.characterId]?.name||'SNICKERS'} schmort als Cartoonfigur am Grillspieß. Hasenbein hat seinen Erzfeind besiegt!</p><button class="secondary-button" id="hasenbeinSkipVictory">ZUM ABSPANN ↗</button>`);
      $('hasenbeinSkipVictory').onclick=showHasenbeinCredits;tone(410,.25,'triangle',.05,670);return;
    }
    mode='hasenbeinResult';updateHasenbeinHud();$('hasenbeinHud').classList.add('hidden');
    showOverlay(`<span class="eyebrow">HASENBEIN MODUS · ${hasenbeinDifficulty.toUpperCase()}</span><h2 id="overlayTitle">${characterRoster[hasenbeinRival?.characterId]?.name||'SNICKERS'} GEWINNT DIE REVANCHE.</h2><p>Hasenbein unterlag in seiner eigenen Phase ${hasenbeinPhase} von ${hasenbeinMaxPhases}. Wähle einen anderen Hall-Build oder versuche es erneut. Kampfzeit: ${formatTime(hasenbeinDuelTime)}. Kampagne und Endloslauf bleiben gespeichert.</p><div class="overlay-actions"><button class="primary-button" id="hasenbeinAgain">ANDEREN BUILD WÄHLEN ↗</button><button class="secondary-button" id="hasenbeinLeave">HAUPTMENÜ</button></div>`);
    $('hasenbeinAgain').onclick=showHasenbeinSelect;$('hasenbeinLeave').onclick=goMenu;
  }
  // Reverse of General Hasenbein's campaign encounter: the player owns the boss phases.
  // The chosen Hall of Fame Snickers retains one health bar for the whole duel.
  function updateHasenbein(dt){
    const rival=hasenbeinRival;if(!rival)return;
    const playerFrom29={x:player.x,y:player.y};
    hasenbeinDuelTime+=dt;music(dt);
    player.invuln=Math.max(0,player.invuln-dt);rival.invuln=Math.max(0,rival.invuln-dt);
    rival.shieldCd=Math.max(0,(rival.shieldCd||0)-dt);if(rival.shieldReady&&rival.shieldUsed&&rival.shieldCd===0)rival.shieldUsed=false;
    rival.lifeStealCd=Math.max(0,(rival.lifeStealCd||0)-dt);
    hasenbeinSpecialCd=Math.max(0,hasenbeinSpecialCd-dt);hasenbeinDashCd=Math.max(0,hasenbeinDashCd-dt);
    hasenbeinFanCd=Math.max(0,hasenbeinFanCd-dt);hasenbeinShockCd=Math.max(0,hasenbeinShockCd-dt);
    hasenbeinGuardCd=Math.max(0,hasenbeinGuardCd-dt);hasenbeinGuardTime=Math.max(0,hasenbeinGuardTime-dt);hasenbeinCallCd=Math.max(0,hasenbeinCallCd-dt);
    let mx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+touch.x;
    let my=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0)+touch.y;
    const len=Math.hypot(mx,my);if(len>1){mx/=len;my/=len;}player.moving=len>.1;
    hasenbeinIdleTime=len>.1||hasenbeinWindup>0||hasenbeinDashTime>0?Math.max(0,hasenbeinIdleTime-dt*2):Math.min(3,hasenbeinIdleTime+dt);
    if(hasenbeinWindup>0){hasenbeinWindup-=dt;player.moving=false;if(hasenbeinRamAutoAim&&hasenbeinWindup>.16)hasenbeinRamAngle=Math.atan2(rival.y-player.y,rival.x-player.x);if(hasenbeinWindup<=0){hasenbeinDashTime=.68;player.dashX=Math.cos(hasenbeinRamAngle);player.dashY=Math.sin(hasenbeinRamAngle);}}
    if(hasenbeinDashTime>0){
      hasenbeinDashTime=Math.max(0,hasenbeinDashTime-dt);
      if(hasenbeinRamAutoAim){const target=Math.atan2(rival.y-player.y,rival.x-player.x);hasenbeinRamAngle+=clamp(angleDelta(target,hasenbeinRamAngle),-dt*1.2,dt*1.2);player.dashX=Math.cos(hasenbeinRamAngle);player.dashY=Math.sin(hasenbeinRamAngle);}
      player.x+=player.dashX*555*dt;player.y+=player.dashY*555*dt;player.invuln=Math.max(player.invuln,.13);
    }
    else if(hasenbeinWindup<=0){player.x+=mx*player.speed*dt;player.y+=my*player.speed*dt;}
    const proposedMove29=Math.hypot(player.x-playerFrom29.x,player.y-playerFrom29.y);resolveDuelMotion29(player,playerFrom29);
    if(hasenbeinDashTime>0&&proposedMove29>.01&&dist(player,playerFrom29)<proposedMove29*.12)hasenbeinDashTime=0;
    player.face=rival.x<player.x?-1:1;player.phase=(player.phase||0)+dt*4;
    if(hasenbeinDashTime>0&&!hasenbeinDashHit&&dist(player,rival)<player.r+rival.r+13){hasenbeinDashHit=true;hasenbeinHitRival(hasenbeinDamage(27+hasenbeinPhase*2));burst(rival.x,rival.y,'#eab46e',18,170);}
    if(dist(player,rival)<player.r+rival.r-8&&hasenbeinDashTime<=0)hasenbeinHurt(.65);

    // Boss pressure remains automatic, but only the player may order the ram.
    // It no longer interrupts movement or silently spends the SPACE cooldown.
    hasenbeinAttackCd-=dt;
    if(hasenbeinAttackCd<=0&&hasenbeinWindup<=0){
      const enraged=hasenbeinPhase>=2,a=Math.atan2(rival.y-player.y,rival.x-player.x);
      hasenbeinAttackPattern=(hasenbeinAttackPattern+1)%5;
      if(hasenbeinAttackPattern===0){for(const off of [-.11,0,.11])hasenbeinShot(player.x,player.y,a+off,260,hasenbeinDamage(2.8),'hasenbein',off===0);}
      else if(hasenbeinAttackPattern===1){const count=enraged?18:13;for(let i=0;i<count;i++)hasenbeinShot(player.x,player.y,a+i*TAU/count,enraged?225:185,hasenbeinDamage(2.5),'hasenbein');}
      else if(hasenbeinAttackPattern===2){hasenbeinHazards.push({x:rival.x,y:rival.y,r:enraged?138:112,wait:1.05,life:.35,hit:false,damage:hasenbeinDamage(7)},{x:clamp(rival.x+rnd(-180,180),65,W-65),y:clamp(rival.y+rnd(-150,150),140,H-55),r:88,wait:1.45,life:.35,hit:false,damage:hasenbeinDamage(5)});}
      else {const count=enraged?7:5;for(let i=0;i<count;i++)hasenbeinShot(player.x,player.y,a+(i-(count-1)/2)*.14,enraged?275:220,hasenbeinDamage(3),'hasenbein');}
      hasenbeinAttackCd=enraged?1.34:1.74;
    }
    for(const hazard of hasenbeinHazards){
      hazard.wait-=dt;
      if(hazard.track>0&&hazard.wait>.22){const follow=Math.min(1,dt*4.5);hazard.x+=(rival.x-hazard.x)*follow;hazard.y+=(rival.y-hazard.y)*follow;hazard.track-=dt;}
      if(hazard.wait<=0&&!hazard.hit){hazard.hit=true;burst(hazard.x,hazard.y,'#e4b075',14,120);if(dist(hazard,rival)<hazard.r+rival.r)hasenbeinHitRival(hazard.damage);}
      if(hazard.hit)hazard.life-=dt;
    }
    hasenbeinHazards=hasenbeinHazards.filter(h=>h.life>0);

    // General Hasenbein summons three rabbits every nine seconds, four while enraged.
    hasenbeinSummonCd-=dt;
    if(hasenbeinSummonCd<=0){hasenbeinSummonCd=hasenbeinPhase>=2?6.5:9;summonHasenbeinBunnies(hasenbeinPhase>=2?4:3);}
    for(const bunny of hasenbeinMinions){bunny.phase+=dt*5;bunny.hit=Math.max(0,bunny.hit-dt);bunny.fireCd-=dt;
      const dx=rival.x-bunny.x,dy=rival.y-bunny.y,d=Math.hypot(dx,dy)||1;
      if(d>80){const from29={x:bunny.x,y:bunny.y};bunny.x+=dx/d*(bunny.type==='runner'?136:92)*dt;bunny.y+=dy/d*(bunny.type==='runner'?136:92)*dt;resolveDuelMotion29(bunny,from29,true);}
      if(d<280&&bunny.fireCd<=0){hasenbeinShot(bunny.x,bunny.y,Math.atan2(dy,dx),240,hasenbeinDamage(1.7),'hasenbein');bunny.fireCd=2.2;}
    }
    hasenbeinMinions=hasenbeinMinions.filter(b=>b.hp>0);
    updateHasenbeinKarnil(dt);

    // Snickers fights as the selected build; its attacks never advance with boss phases.
    const dx=player.x-rival.x,dy=player.y-rival.y,d=Math.hypot(dx,dy)||1;
    const ideal=260+Math.sin(hasenbeinDuelTime*.8)*35,dir=d<ideal-50?-1:d>ideal+50?1:0,strafe=Math.sin(hasenbeinDuelTime*1.9)>0?1:-1;
    const rivalFrom29={x:rival.x,y:rival.y};
    rival.x=clamp(rival.x+(dx/d*dir*.75-dy/d*strafe*.55)*rival.speed*dt,65,W-65);
    rival.y=clamp(rival.y+(dy/d*dir*.75+dx/d*strafe*.55)*rival.speed*dt,157,H-65);
    rival.dodgeCd-=dt;
    resolveDuelMotion29(rival,rivalFrom29,true);
    if(rival.dodgeChance>0&&rival.dodgeCd<=0){rival.dodgeCd=3.8;const from29={x:rival.x,y:rival.y};rival.x-=dy/d*85;rival.y+=dx/d*85;resolveDuelMotion29(rival,from29);burst(rival.x,rival.y,'#e4a86e',7,60);}
    rival.face=player.x<rival.x?-1:1;rival.angle=Math.atan2(player.y-rival.y,player.x-rival.x);rival.phase+=dt*8;rival.hit=Math.max(0,(rival.hit||0)-dt);
    rival.companionCd-=dt;
    if(rival.companionCount>0&&rival.companionCd<=0){
      rival.companionCd=Math.max(3.2,5.4-rival.companionCount*.22);
      const n=Math.min(3,rival.companionCount),a=Math.atan2(player.y-rival.y,player.x-rival.x);
      for(let i=0;i<n;i++)hasenbeinShot(rival.x+(i-1)*15,rival.y-30,a+(i-(n-1)/2)*.18,280+16*n,.46+(hardMode?.14:0),'snickers');
      burst(rival.x,rival.y-30,'#d8c495',5,55);
    }
    rival.fireCd-=dt;if(rival.fireCd<=0){
      rival.fireCd=clamp(rival.fireRate/(rival.damage*.26+.6),.17,.45);
      rival.shotCount=(rival.shotCount||0)+1;
      const bait=rival.shotCount%4===0?[...hasenbeinMinions,...(hasenbeinKarnil?.hp>0?[hasenbeinKarnil]:[])].filter(b=>dist(rival,b)<360).sort((a,b)=>dist(rival,a)-dist(rival,b))[0]:null;
      const a=bait?Math.atan2(bait.y-rival.y,bait.x-rival.x):rival.angle;
      const n=rival.nutFan||rival.weaponCount>=4?3:1;
      for(let i=0;i<n;i++)hasenbeinShot(rival.x,rival.y,a+(i-(n-1)/2)*.20,345+15*rival.weaponCount,clamp(.62*rival.damage*(Math.random()<rival.crit?1.35:1)*(hasenbeinDifficulty==='impossible'?1.35:hasenbeinDifficulty==='hard'?1.15:1),.58,2.4),'snickers');
      if(rival.rearNut&&Math.random()<.18)hasenbeinShot(rival.x,rival.y,a+Math.PI,290,.55,'snickers');
      if(rival.orbit&&Math.random()<.28)for(let i=0;i<5;i++)hasenbeinShot(rival.x,rival.y,i*TAU/5+hasenbeinDuelTime,240,.7,'snickers');
      if(rival.sentry&&Math.random()<.25)hasenbeinShot(rival.x,rival.y-35,rival.angle,430,.95,'snickers');
    }
    rival.patternCd-=dt;if(rival.patternCd<=0&&!rival.charge){
      rival.charge={x:player.x,y:player.y,wait:1.05,r:hasenbeinDifficulty==='impossible'?112:88};
      rival.patternCd=((hasenbeinDifficulty==='impossible'?3.3:hasenbeinDifficulty==='hard'?3.9:4.7)-(rival.weaponCount>=6?.3:0))*(hasenbeinIdleTime>1.5?.76:1);
    }
    if(rival.charge){rival.charge.wait-=dt;if(rival.charge.wait<=0){
      const strike=rival.charge;rival.charge=null;burst(strike.x,strike.y,'#ef885a',24,150);
      if(dist(player,strike)<strike.r+player.r*.35)hasenbeinHurt(hasenbeinDifficulty==='impossible'?3.8:hasenbeinDifficulty==='hard'?2.95:2.4);
      if(rival.weaponCount>=4)for(let i=0;i<8;i++)hasenbeinShot(strike.x,strike.y,i*TAU/8,260,.75,'snickers');
    }}
    for(const s of hasenbeinShots){if(s.life<=0)continue;s.life-=dt;if(s.life<=0)continue;const before={x:s.x,y:s.y};if(s.homing&&s.owner==='hasenbein'){
      const speed=Math.hypot(s.vx,s.vy),angle=Math.atan2(s.vy,s.vx),target=Math.atan2(rival.y-s.y,rival.x-s.x);
      const next=angle+clamp(angleDelta(target,angle),-dt*1.1,dt*1.1);s.vx=Math.cos(next)*speed;s.vy=Math.sin(next)*speed;
    }s.x+=s.vx*dt;s.y+=s.vy*dt;
      if(duelSegmentBlocked29(before,s,s.r)){s.life=0;continue;}
      if(s.owner==='snickers'){
        const minion=hasenbeinMinions.find(b=>b.hp>0&&segmentDistance(b,before,s)<b.r+s.r);
        if(minion){s.life=0;minion.hp-=1;minion.hit=.15;}
        else if(hasenbeinKarnil?.hp>0&&segmentDistance(hasenbeinKarnil,before,s)<hasenbeinKarnil.r*.7+s.r){
          s.life=0;hasenbeinKarnil.hp=Math.max(0,hasenbeinKarnil.hp-s.damage*.72);hasenbeinKarnil.hit=.2;
          if(hasenbeinKarnil.hp===0){burst(hasenbeinKarnil.x,hasenbeinKarnil.y,'#e5aa8a',27,140);announce('KARNIL IST ERSCHÖPFT','HASENBEIN KÄMPFT WEITER');}
        }
        else if(s.life>0&&segmentDistance(player,before,s)<player.r+s.r){s.life=0;const prior=player.hp;hasenbeinHurt(s.damage);if(rival.vampire&&player.hp<prior&&rival.lifeStealCd<=0){rival.lifeStealCd=18;rival.hp=Math.min(rival.maxHp,rival.hp+Math.min(8,rival.maxHp*.008));}}
      }else if(s.life>0&&segmentDistance(rival,before,s)<rival.r+s.r){s.life=0;hasenbeinHitRival(s.damage);}
    }
    hasenbeinMinions=hasenbeinMinions.filter(b=>b.hp>0);
    hasenbeinShots=hasenbeinShots.filter(s=>s.life>0&&s.x>0&&s.x<W&&s.y>110&&s.y<H);
    if(rival.hp<=0)endHasenbeinDuel(true);
    else if(player.hp<=0)nextHasenbeinPhase();
    else updateHasenbeinHud();
  }
  function renderHasenbein(){
    camX=clamp(player.x-viewW/2,0,Math.max(0,W-viewW));camY=clamp(player.y-viewH/2,0,Math.max(0,H-viewH));
    ctx.setTransform(dpr*scale,0,0,dpr*scale,-camX*dpr*scale,-camY*dpr*scale);ctx.drawImage(ground,0,0);
    if(hasenbeinRival.charge){const t=hasenbeinRival.charge;ctx.fillStyle='#d0493d44';ctx.strokeStyle='#ffab83';ctx.lineWidth=4;ctx.beginPath();ctx.arc(t.x,t.y,t.r,0,TAU);ctx.fill();ctx.stroke();}
    for(const h of hasenbeinHazards){ctx.fillStyle='#e5a16031';ctx.strokeStyle='#f4ce81';ctx.lineWidth=3;ctx.beginPath();ctx.arc(h.x,h.y,h.r,0,TAU);ctx.fill();ctx.stroke();}
    if(hasenbeinWindup>0){ctx.strokeStyle='#ffe0a5';ctx.lineWidth=14;ctx.globalAlpha=.55;ctx.setLineDash([22,12]);ctx.beginPath();ctx.moveTo(player.x,player.y);ctx.lineTo(player.x+Math.cos(hasenbeinRamAngle)*380,player.y+Math.sin(hasenbeinRamAngle)*380);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;}
    for(const bunny of hasenbeinMinions){ctx.save();ctx.strokeStyle='#eed080';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(bunny.x,bunny.y+13,22,9,0,0,TAU);ctx.stroke();ctx.restore();drawRabbit({...bunny,hasenbeinAlly:true,dead:false});}
    if(hasenbeinKarnil?.hp>0){
      ctx.save();ctx.strokeStyle='#f4c484';ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(hasenbeinKarnil.x,hasenbeinKarnil.y+32,hasenbeinKarnil.r*.8,19,0,0,TAU);ctx.stroke();ctx.restore();
      drawRabbit({...hasenbeinKarnil,hasenbeinControlled:true,face:hasenbeinRival.x<hasenbeinKarnil.x?-1:1,dead:false});
      ctx.fillStyle='#352b2a';ctx.fillRect(hasenbeinKarnil.x-53,hasenbeinKarnil.y-119,106,8);
      ctx.fillStyle='#f7ca8d';ctx.fillRect(hasenbeinKarnil.x-52,hasenbeinKarnil.y-118,104*clamp(hasenbeinKarnil.hp/hasenbeinKarnil.maxHp,0,1),6);
    }
    drawRabbit({...player,type:'boss',hasenbeinControlled:true,dead:false,enraged:hasenbeinPhase>=2});drawHamster(hasenbeinRival);
    if(player.invuln>0){ctx.save();ctx.strokeStyle='#ffd78e';ctx.globalAlpha=.3+.2*Math.sin(ambientTime*15);ctx.lineWidth=3;ctx.beginPath();ctx.arc(player.x,player.y,player.r+8,0,TAU);ctx.stroke();ctx.restore();}
    if(hasenbeinGuardTime>0){ctx.save();ctx.fillStyle='#f7d99029';ctx.strokeStyle='#f7d990';ctx.lineWidth=5;ctx.beginPath();ctx.arc(player.x,player.y,player.r+16+Math.sin(ambientTime*13)*2,0,TAU);ctx.fill();ctx.stroke();ctx.restore();}
    for(const s of hasenbeinShots){ellipse(ctx,s.x,s.y,s.r,s.r,s.owner==='hasenbein'?'#dfad72':characterRoster[hasenbeinRival?.characterId||'snickers'].color);}
    if(hasenbeinDashTime>0){ctx.strokeStyle='#f4ce81';ctx.lineWidth=5;ctx.beginPath();ctx.arc(player.x,player.y,player.r+12,0,TAU);ctx.stroke();}
    for(const p of particles){ctx.save();ctx.globalAlpha=clamp(p.life/p.maxLife,0,1);if(p.type==='beam'){ctx.strokeStyle=p.color;ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x2,p.y2);ctx.stroke();}else if(p.type==='ring'){ctx.strokeStyle=p.color;ctx.lineWidth=4;ctx.beginPath();ctx.arc(p.x,p.y,180*(1-p.life/p.maxLife),0,TAU);ctx.stroke();}else ellipse(ctx,p.x,p.y,p.r,p.r*.8,p.color);ctx.restore();}
    for(const f of floaters){ctx.save();ctx.globalAlpha=Math.min(1,f.life*2);ctx.font='bold 16px Barlow, Arial';ctx.textAlign='center';ctx.fillStyle=f.color;ctx.fillText(f.text,f.x,f.y);ctx.restore();}
  }
  const hasenbeinOriginalUpdate=update,hasenbeinOriginalRender=render,hasenbeinOriginalDash=useDash,hasenbeinOriginalWeapon=useWeapon,hasenbeinOriginalCycle=cycleWeapon,hasenbeinOriginalMenu=goMenu,hasenbeinOriginalPause=pauseGame;
  update=function(dt){if(hasenbeinMode){if(mode==='playing')updateHasenbein(dt);return;}hasenbeinOriginalUpdate(dt);};
  render=function(dt){if(hasenbeinMode&&hasenbeinRival){renderHasenbein();return;}hasenbeinOriginalRender(dt);};
