    path(ctx,[[-10,-7],[-37,-23],[-27,9],[-10,8]],'#736a65');path(ctx,[[10,-7],[37,-23],[27,9],[10,8]],'#736a65');ellipse(ctx,0,-4,17,17,'#827768');
