  updateHud=function(){beforeKnollHud();if(knollQuest?.status==='hunting'&&knollQuest.spawned&&!boss){$('waveObjective').textContent+=` · GOLDENE FEDER: ${Math.max(0,Math.ceil(knollQuest.expiresAt-waveTime))} s`;}};
