    for(const [i,dx] of [-46,46].entries())hazards.push({type:'friendlyMortar',x:clamp(t.x+dx,55,W-55),y:clamp(t.y+(i?20:-20),120,H-55),r:96,wait:.48+i*.24,life:.35,hit:false,damage:21*sm,friendly:true});
