      if(ottahBoss)drawPixelBossAura(x,y,e.ottahPhase||1,(e.ottahPhase||1)>=3?'#fff1ad':'#e38c66',(e.ottahPhase||1)>=2?'#ffd7a8':'#f4c46f');
