      const buttons=Array.from($('overlayContent').querySelectorAll('button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), a[href], summary')).filter(el=>el.offsetWidth>0);const first=buttons[0],last=buttons[buttons.length-1];
