  function worldStatPrice(id){const bought=Object.values(player.scorePerks||{}).reduce((a,n)=>a+n,0),base={damage:5400,speed:4300,fireRate:5600,dash:5000,powerLuck:4200,dodge:4900,heart:6200,ammo:5400,shuffle:3500}[id]||5000;return Math.round(base*Math.pow(1.16,Math.min(16,bought))*Math.pow(1.10,Math.min(8,player.scorePerks[id]||0))*(impossibleMode?1.55:hardMode?1.35:1)/100)*100;}
