    if(!worldOutside())return;
    worldTick-=dt;if(worldTick>0)return;worldTick=.12;
    const cell=Math.floor(player.x/512)+','+Math.floor(player.y/512);if(!exploration.explored.includes(cell))exploration.explored.push(cell);
