  const worldUpdate=update;
  update=function(dt){if(mode!=='playing')return;const travelOrigin={x:player.x,y:player.y};worldDelta=dt;if(worldOutside()){enemies=enemies.filter(e=>{if(e.worldGuardian&&dist(e,player)>1800){const p=exploration.pois.find(p=>p.id===e.worldPoi);if(p){p.hp=e.hp;p.active=false;}return false;}return true;});if(player.lominarWorm&&(Math.abs(player.lominarX-player.x)>viewW*.65||Math.abs(player.lominarY-player.y)>viewH*.65)){player.lominarX=player.x-viewW*.48;player.lominarY=player.y+90;player.lominarDir=1;}if(player.potencyMinister&&Math.abs((player.ministerX||0)-player.x)>viewW*.5)player.ministerX=player.x-viewW*.42;}for(const e of enemies)e.worldFrom={x:e.x,y:e.y};worldUpdate(dt);if(worldOutside()&&Math.hypot(player.x-travelOrigin.x,player.y-travelOrigin.y)<300){const dx=player.x-travelOrigin.x,dy=player.y-travelOrigin.y;if(player.lominarWorm){player.lominarX+=dx;player.lominarY+=dy;}if(player.potencyMinister)player.ministerX+=dx;}updateWorld(dt);};
