  const newEnemies24={bellBeetle:{name:'KÄFER KLINGELKLAUS',stats:[7,58,23,155],color:'#d5b561',species:'beetle',icon:'!',unlock:'Alle Modi'},roadMole:{name:'BODO BODENSCHADEN',stats:[4,72,19,140],color:'#b78b68',species:'mole',icon:'!',unlock:'Alle Modi'},parcelWasp:{name:'WESPE EXPRESS',stats:[1.6,118,15,75],color:'#e1b34e',species:'wasp',icon:'!',unlock:'Alle Modi'},sporeDrummer:{name:'PILZ PERCUSSION',stats:[5,55,20,150],color:'#b790d1',species:'mushroom',icon:'!',unlock:'Alle Modi'},cardCrow:{name:'KRAHLO CASINO',stats:[6,62,21,175],color:'#c87570',species:'crow',icon:'!',unlock:'Alle Modi'}};
