  function hordeVisible24(e,pad=80){return Math.abs(e.x-player.x)<viewW/2+pad&&Math.abs(e.y-player.y)<viewH/2+pad;}
  balanceSpawnCap=function(){return hordeRules24().cap+(endlessMode?Math.min(16,Math.floor(wave/15)*2):0)-(getMiniBoss()?8:0);};
  balanceSpawnInterval=function(){const h=hordeRules24(),progress=clamp(waveTime/currentWaveLength(),0,1),growth=endlessMode?Math.min(1.7,1+wave*.018):1+.035*Math.min(campaignProgress25(),8);return Math.max(.48,h.interval*(1-.22*progress)/growth)*(waveTime%55>47?1.7:1)*(getMiniBoss()?1.5:1);};
  const oldSpawn24=spawnEnemy;
