  function hordeSpecial24(){const act=Math.min(2,Math.floor(campaignProgress25()/3)),regular=endlessMode?[...new Set([...endlessEnemyPool(wave).filter(id=>!['bunny','runner','pigDrone','parcelWasp'].includes(id)),...Object.keys(newEnemies24).filter(id=>id!=='parcelWasp')])]:act===0?['gunner','brute','bellBeetle','roadMole','sporeDrummer','cardCrow']:act===1?['rabid','gatling','sniper','sapper','splitter','bellBeetle','roadMole','sporeDrummer','cardCrow']:['pigRammer','pigMortar','pigCannon','pigHowler','bellBeetle','roadMole','sporeDrummer','cardCrow'];return hardEnemyChoice(regular[Math.floor(Math.random()*regular.length)]);}
  function tickHordes24(dt){if(boss||worldRoomActive()||waveTime>=currentWaveLength())return;spawnTimer-=dt;if(spawnTimer>0)return;spawnTimer=balanceSpawnInterval();const live=enemies.filter(e=>!e.dead),cap=balanceSpawnCap(),special=live.filter(e=>!['bunny','runner','parcelWasp','pigDrone'].includes(e.type)&&!e.miniBoss).length,limit=impossibleMode?8:hardMode?6:4,n=Math.min(hordeRules24().size,cap-live.length);for(let i=0;i<n;i++){let type=i===0&&waveTime>15&&special<limit&&Math.random()<.58?hordeSpecial24():Math.random()<.22?'parcelWasp':Math.random()<.48?'runner':campaignProgress25()>=6?'pigDrone':'bunny';if(type==='cardCrow'&&live.filter(e=>e.type===type).length>=(hardMode?2:1))type='runner';spawnEnemy(type);}}
  const nearest24=nearestTarget;
