    for(let rad=16;rad<=1024;rad+=16)for(let i=0;i<48;i++){const a=i*TAU/48,px=x+Math.cos(a)*rad,py=y+Math.sin(a)*rad;if(valid(px,py))return{x:px,y:py};}
