      for(const p of saved.carrotVines||[]){const age=2.45-p.life,growth=Math.min(1,age*4),pulse=Math.max(0,1-p.tick/.65);drawAbility(age<.2?'vine-bud':'vine-bloom',p.x,p.y-15,150*growth,135*growth,0,.9);if(p.pulses){pixelRing(p.x,p.y+10,45+pulse*75,'#abd16e',2,(1-pulse)*.45);}}
      for(const p of saved.soundWalls||[]){const alpha=Math.min(1,p.life*2),pulse=reducedMotion?0:Math.sin(motionTime*12)*3;drawAbility('horn-wave',p.x,p.y,145+pulse,210,p.a,alpha*.77);drawAbility('brass-resonator',p.x-Math.cos(p.a)*46,p.y-Math.sin(p.a)*46,58,75,0,alpha);}
      drawVisualEffects();
