      if(b.normalNut&&!b.characterAttack){const a=b.a||0,r=b.r||6;pixelLine(b.x-Math.cos(a)*13,b.y-Math.sin(a)*13,b.x,b.y,b.frost?'#addef0':b.chain?'#c1a3ea':'#dbb173',2,.48,3);ctx.save();ctx.translate(Math.round(b.x),Math.round(b.y));ctx.rotate(a+motionTime*9);const size=Math.max(17,r*2.5);ctx.drawImage(art.detail('hazelnut'),-size/2,-size/2,size,size);ctx.restore();return true;}
