        if(scene.dataset.scene==='hasenbeinVictory'){const prior=scene.previousElementSibling;if(prior?.tagName==='P')prior.insertAdjacentHTML('beforeend',' Hasenbein setzt zur Siegesrede an. Karnil reicht ihm eine Möhre. „Erst essen. Du redest mit vollem Mund leiser.“');}
