      if(mode==='paftiCutscene')return 'pafti';
      if(mode==='playing'){
        const bossTheme=paftiBoss&&!paftiBoss.dead?'pafti':boss&&!boss.dead?(boss.herbert?'herbert':boss.ottah?'ottah':boss.karnil?'karnil':boss.cyber?'cyber':'hasenbein'):hasenbeinMode?(hasenbeinKarnil?'karnil':'hasenbein'):enemies.some(e=>!e.dead&&(e.troll||e.type==='bergTroll'||e.type==='knoll'))?'troll':null;
        lastBattleTrack=bossTheme||(endlessMode?'endless':stageVisual===1?'lab':stageVisual===2?'quarry':stageVisual===3?'kitchen':stageVisual>=4?'endless':{snickers:'garden',raffzahn:'sewer',krustenbraten:'kitchen',slanny:'swamp',koettitroeter:'stage'}[player?.characterId]||'garden');return lastBattleTrack;
      }
