    function withNewSound(fn,args){suppressLegacySfx++;try{return fn(...args);}finally{suppressLegacySfx--;}}
    const scoredFire=fire;
    fire=function(...args){const result=withNewSound(scoredFire,args);if(result){soundEffect({snickers:'shot',raffzahn:'bite',krustenbraten:'pan',slanny:'carrot',koettitroeter:'horn'}[player?.characterId]||'shot');if(player?.characterId==='krustenbraten'){const pool=player.pigPools?.at(-1);if(pool)visual('pan-impact',pool.x,pool.y-15,0,90,.21);}}return result;};
    const scoredWeapon=useWeapon;
    useWeapon=function(...args){const before=player?.weaponShots||0,id=player?.weapons?.[player.weaponIndex],result=withNewSound(scoredWeapon,args);if(player&&(player.weaponShots||0)>before){const name={ratWhistle:'trap',pigPan:'fire',carrotCyclone:'vines',trollFanfare:'resonance'}[id]||(/fire|flame|cream|sausage/i.test(id)?'fire':/tesla|storm|laser|singularity/i.test(id)?'resonance':'explosion');soundEffect(name);if(id==='nutBomb')visual('ember-burst',player.x,player.y-12,0,145,.35);}return result;};
    const scoredDash=useDash;
